interface LanguageContextValue {
  language: Language
  setLanguage: (language: Language) => void
  t: (key: TranslationKey, values?: Record<string, string | number>) => string
}

const LanguageContext = createContext<LanguageContextValue | null>(null)

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const stored = window.localStorage.getItem('coda-language')
    return stored === 'zh' ? 'zh' : 'en'
  })
  function setLanguage(next: Language) {
    setLanguageState(next)
    window.localStorage.setItem('coda-language', next)
  }
  useEffect(() => {
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : 'en'
  }, [language])
  function t(key: TranslationKey, values: Record<string, string | number> = {}) {
    let value: string = workflowExtraTranslations[language][key] ?? translations[language][key] ?? workflowTranslations[language][key] ?? (language === 'zh' ? chineseReviewTranslations[key] : undefined) ?? workflowExtraTranslations.en[key] ?? translations.en[key] ?? workflowTranslations.en[key] ?? key
    Object.entries(values).forEach(([name, replacement]) => {
      value = value.replaceAll(`{${name}}`, String(replacement))
    })
    return value
  }
  return <LanguageContext.Provider value={{ language, setLanguage, t }}>{children}</LanguageContext.Provider>
}

export function useLanguage() {
  const context = useContext(LanguageContext)
  if (!context) throw new Error('useLanguage must be used inside LanguageProvider')
  return context
}
